// Package: Microsoft.Extensions.AI
// Install: dotnet add package Microsoft.Extensions.AI.OpenAI --version 9.*

using Microsoft.Extensions.AI;
using OpenAI;

public sealed class RagPipeline
{
    private readonly IEmbeddingGenerator<string, Embedding<float>> _embeddingGenerator;
    private readonly IChatClient _chatClient;
    private const int MaxContextChunks = 3;

    public RagPipeline(OpenAIClient openAIClient)
    {
        _embeddingGenerator = openAIClient.AsEmbeddingGenerator("text-embedding-3-small");
        _chatClient = openAIClient.AsChatClient("gpt-4o-mini");
    }

    public async Task<string> QueryAsync(
        string question,
        string context,
        CancellationToken cancellationToken = default)
    {
        // 1. Embed the question (for real vector-store search)
        Embedding<float> queryEmbedding = await _embeddingGenerator.GenerateAsync(
            question,
            cancellationToken: cancellationToken);

        // 2. Build the augmented prompt with retrieved context
        var messages = new List<ChatMessage>
        {
            new SystemMessage("Answer using ONLY the provided context. "
                            + "If the answer is not in the context, say 'I don't know.'"),
            new UserMessage($"Context:\n{context}\n\nQuestion: {question}")
        };

        // 3. Generate the grounded answer
        ChatResponse response = await _chatClient.GetResponseAsync(
            messages,
            cancellationToken: cancellationToken);

        return response.Text;
    }
}

// Usage example
var pipeline = new RagPipeline(new OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY")!));

string answer = await pipeline.QueryAsync(
    "What causes a 500 error?",
    context: "A 500 error indicates an unexpected condition on the server. "
           + "Common causes include unhandled exceptions, database failures, and resource exhaustion.");

Console.WriteLine(answer);
// Expected output: A 500 error indicates an unexpected condition on the server...
